function exFolder($v):string{return trim(substr(preg_replace('/[^a-zA-Z0-9_-]+/','_',strtr((string)$v,['á'=>'a','č'=>'c','ď'=>'d','é'=>'e','ě'=>'e','í'=>'i','ň'=>'n','ó'=>'o','ř'=>'r','š'=>'s','ť'=>'t','ú'=>'u','ů'=>'u','ý'=>'y','ž'=>'z','Á'=>'A','Č'=>'C','Ď'=>'D','É'=>'E','Ě'=>'E','Í'=>'I','Ň'=>'N','Ó'=>'O','Ř'=>'R','Š'=>'S','Ť'=>'T','Ú'=>'U','Ů'=>'U','Ý'=>'Y','Ž'=>'Z'])),0,100),'_')?:'projekt';}
function exPhotoPath(string $url):?string{$parts=parse_url($url);if($parts===false||isset($parts['user'])||isset($parts['pass']))return null;if(isset($parts['host'])&&!in_array(strtolower($parts['host']),[strtolower((string)parse_url(svmUrl(),PHP_URL_HOST))],true))return null;if(isset($parts['scheme'])&&!in_array(strtolower($parts['scheme']),['http','https'],true))return null;$path=rawurldecode($parts['path']??'');if(str_contains($path,"\0")||str_contains($path,'\\'))return null;if(str_starts_with($path,'/map/public/'))$path=substr($path,strlen('/map/public/'));$path=ltrim($path,'/');$folder=explode('/',$path)[0];if(!in_array($folder,['uploads','photos'],true))return null;$root=realpath(__DIR__.'/../'.$folder);$file=realpath(__DIR__.'/../'.$path);return $root&&$file&&str_starts_with($file,$root.DIRECTORY_SEPARATOR)&&is_file($file)&&is_readable($file)?$file:null;}
